import{_ as e}from"./chunks/100.I7A0VXqr.js";import{_ as i,o as a,c as o,ak as n}from"./chunks/framework.DC-k2h36.js";const r="/projects/esp32Sensor/en/latest/assets/1.8roKP9iB.webp",s="/projects/esp32Sensor/en/latest/assets/2.6dUcPTWU.webp",l="/projects/esp32Sensor/en/latest/assets/3.Bdp9SGcv.webp",h="/projects/esp32Sensor/en/latest/assets/4.6kueY5zw.webp",y=JSON.parse('{"title":"6. Light Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/6. Light Sensor.md","filePath":"docs/6. Light Sensor.md"}'),c={name:"docs/6. Light Sensor.md"};function d(g,t,p,m,u,_){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_6-light-sensor" tabindex="-1">6. Light Sensor <a class="header-anchor" href="#_6-light-sensor" aria-label="Permalink to &quot;6. Light Sensor&quot;">​</a></h1><h2 id="_6-1-introduction" tabindex="-1">6.1 Introduction <a class="header-anchor" href="#_6-1-introduction" aria-label="Permalink to &quot;6.1 Introduction&quot;">​</a></h2><p>The light sensor detects ambient light intensity. It is widely used to create interactive projects that respond to changing light levels, such as automated street lighting systems and environmental monitoring equipment.</p><img loading="lazy" height="1156" width="1156" src="'+r+'" class="common_img" style="width:300px;"><h2 id="_6-2-technical-specifications" tabindex="-1">6.2 Technical Specifications <a class="header-anchor" href="#_6-2-technical-specifications" aria-label="Permalink to &quot;6.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Adjustment method</td><td style="text-align:center;">Miniature potentiometer adjustment</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 17.2 mm</td></tr></tbody></table><h2 id="_6-3-hands-on-project" tabindex="-1">6.3 Hands-On Project <a class="header-anchor" href="#_6-3-hands-on-project" aria-label="Permalink to &quot;6.3 Hands-On Project&quot;">​</a></h2><h3 id="_6-3-1-project-overview" tabindex="-1">6.3.1 Project Overview <a class="header-anchor" href="#_6-3-1-project-overview" aria-label="Permalink to &quot;6.3.1 Project Overview&quot;">​</a></h3><p>This project uses the light sensor and onboard RGB LEDs to create a smart night light. When ambient light intensity exceeds the threshold of 80, all RGB LEDs turn off. When ambient light dims and light intensity drops to 80 or below, all RGB LEDs illuminate in white, demonstrating light sensor data acquisition and conditional branch programming logic.</p><h3 id="_6-3-2-hardware-wiring" tabindex="-1">6.3.2 Hardware Wiring <a class="header-anchor" href="#_6-3-2-hardware-wiring" aria-label="Permalink to &quot;6.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the light sensor to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="625" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_6-3-3-adding-extensions" tabindex="-1">6.3.3 Adding Extensions <a class="header-anchor" href="#_6-3-3-adding-extensions" aria-label="Permalink to &quot;6.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Light sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_6-3-4-complete-program-and-analysis" tabindex="-1">6.3.4 Complete Program and Analysis <a class="header-anchor" href="#_6-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;6.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the brightness value of the light sensor connected to port P5 is continuously read to perform conditional judgment:</p><ul><li><p>When the detected brightness is greater than 80, ambient light is sufficient, and all RGB LEDs turn off.</p></li><li><p>When the detected brightness is less than or equal to 80, ambient light is dim, and all RGB LEDs illuminate in white.</p></li></ul></li><li><p>A 0.1 s delay is executed at the end of each loop iteration before repeating the entire light detection process.</p></li></ol><img loading="lazy" height="455" width="759" src="'+h+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/06 Light Sensor.sb3</a>.</strong></p></div><h3 id="_6-3-5-program-upload" tabindex="-1">6.3.5 Program Upload <a class="header-anchor" href="#_6-3-5-program-upload" aria-label="Permalink to &quot;6.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_6-3-6-program-outcome" tabindex="-1">6.3.6 Program Outcome <a class="header-anchor" href="#_6-3-6-program-outcome" aria-label="Permalink to &quot;6.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, the light sensor monitors ambient brightness continuously. When bright light shines on the sensor, the RGB LEDs extinguish. When the light sensor is covered and ambient brightness drops, the RGB LEDs turn on in white automatically, simulating a smart night light that toggles based on ambient light levels.</p>',25)])])}const x=i(c,[["render",d]]);export{y as __pageData,x as default};
